(function(){
  'use strict';
  const widgetId='w202610292108507a495eb';
  const slot=document.getElementById('oreon-newsletter-slot');
  if(!slot)return;
  let observer;
  function mount(){
    const widget=document.getElementById(widgetId);
    if(!widget || !widget.querySelector('form') || !widget.querySelector('._input_form_submit'))return false;
    if(!slot.contains(widget))slot.appendChild(widget);
    const status=slot.querySelector('.oreon-form-status');
    if(status)status.remove();
    // Imweb owns the completion message and displays it after successful submission.
    const complete=document.getElementById('input_form_complete_modal_'+widgetId);
    // Keep native dialogs outside the footer stacking context.
    [complete,document.getElementById('input_form_error_modal_'+widgetId)].forEach(function(modal){
      if(modal && widget.contains(modal))document.body.appendChild(modal);
    });
    const email=widget.querySelector('input[name="input_20ce3780d9878"]');
    if(email){email.type='email';email.required=true;email.autocomplete='email';email.placeholder='Email Address';}
    const submit=widget.querySelector('._input_form_submit');
    submit.textContent='SIGN UP';
    if(!submit.dataset.oreonValidation){
      // Keep Imweb's original submit handler. Validate before its inline click handler runs.
      submit.addEventListener('click',function(event){
        if(email && !email.reportValidity()){event.preventDefault();event.stopImmediatePropagation();}
      },true);
      submit.dataset.oreonValidation='1';
    }
    if(email && !email.dataset.oreonEnter){
      email.addEventListener('keydown',function(event){
        if(event.key==='Enter'){event.preventDefault();submit.click();}
      });
      email.dataset.oreonEnter='1';
    }
    if(observer)observer.disconnect();
    return true;
  }
  if(!mount()){
    observer=new MutationObserver(mount);
    observer.observe(document.body,{childList:true,subtree:true});
    setTimeout(function(){observer.disconnect();},30000);
  }
})();

